1	`timescale 1ns / 1ps
2	`include "CtrlDefine.vh"
3	
4	module CtrlUnit(
5	    input clk,
6	    input rst,
7	
8	    input[31:0] PC,
9	    input[31:0] inst,
10	    input[31:0] imm,
11	    
12	    input ALU_done,
13	    input MEM_done,
14	    input MUL_done,
15	    input DIV_done,
16	    input JUMP_done,
17	    input is_jump,
18	
19	    // IF
20	    output IS_en,
21	
22	    // IS
23	    output[2:0] ImmSel,
24	
25	    // RO/FU
26	    output reg ALU_en, MEM_en, MUL_en, DIV_en, JUMP_en,
27	    output reg[31:0] PC_ctrl,
28	    output reg[31:0] imm_ctrl,
29	    output reg[4:0] rs1_ctrl, rs2_ctrl, 
30	    
31	    // FU
32	    output reg[4:0] JUMP_op,
33	    output reg[3:0] ALU_op,
34	    output reg ALU_use_PC,
35	    output reg ALU_use_imm,
36	    output reg MEM_we,
37	    output reg[2:0] MEM_bhw,
38	    output reg[2:0] MUL_op,
39	    output reg[1:0] DIV_op,
40	    
41	    // WB
42	    output reg[2:0] write_sel,
43	    output reg reg_write,
44	    output reg[4:0] rd_ctrl
45	);
46	    // used in for loop
47	    integer i;
48	
49	    // Function Unit Status
50	    // fields of FUS are defined at CtrlDefine.vh
51	    reg[31:0] FUS[1:5];
52	    reg[31:0] IMM[1:5];
53	
54	    // Register Status
55	    // records which FU will write corresponding reg at WB
56	    reg[2:0] RRS[0:31];
57	
58	    // sometimes an instruction needs PC to execute
59	    // pc record
60	    reg[31:0] PCR[1:5];
61	
62	    wire RO_en;
63	    wire normal_stall;
64	    reg ctrl_stall = 0, IS_flush = 0;
65	
66	    // a jump (JAL/JALR/BXX) instr has issued,
67	    // stop issuing until result is known
68	    wire jump_stall;
69	
70	    // instruction field
71	    wire[6:0] funct7 = inst[31:25];
72	    wire[2:0] funct3 = inst[14:12];
73	    wire[6:0] opcode = inst[6:0];
74	    wire[4:0] rd = inst[11:7];
75	    wire[4:0] rs1 = inst[19:15];
76	    wire[4:0] rs2 = inst[24:20];
77	
78	    // type specification
79	    wire Rop = opcode == 7'b0110011;
80	    wire Iop = opcode == 7'b0010011;
81	    wire Bop = opcode == 7'b1100011;
82	    wire Lop = opcode == 7'b0000011;
83	    wire Sop = opcode == 7'b0100011;
84	
85	    wire funct7_0  = funct7 == 7'h0;
86	    wire funct7_1  = funct7 == 7'h1;
87	    wire funct7_32 = funct7 == 7'h20;
88	
89	    wire funct3_0 = funct3 == 3'h0;
90	    wire funct3_1 = funct3 == 3'h1;
91	    wire funct3_2 = funct3 == 3'h2;
92	    wire funct3_3 = funct3 == 3'h3;
93	    wire funct3_4 = funct3 == 3'h4;
94	    wire funct3_5 = funct3 == 3'h5;
95	    wire funct3_6 = funct3 == 3'h6;
96	    wire funct3_7 = funct3 == 3'h7;
97	
98	    wire ADD  = Rop & funct3_0 & funct7_0;
99	    wire SUB  = Rop & funct3_0 & funct7_32;
100	    wire SLL  = Rop & funct3_1 & funct7_0;
101	    wire SLT  = Rop & funct3_2 & funct7_0;
102	    wire SLTU = Rop & funct3_3 & funct7_0;
103	    wire XOR  = Rop & funct3_4 & funct7_0;
104	    wire SRL  = Rop & funct3_5 & funct7_0;
105	    wire SRA  = Rop & funct3_5 & funct7_32;
106	    wire OR   = Rop & funct3_6 & funct7_0;
107	    wire AND  = Rop & funct3_7 & funct7_0;
108	
109	    wire MUL    = Rop & funct3_0 & funct7_1;
110	    wire MULH   = Rop & funct3_1 & funct7_1;
111	    wire MULHSU = Rop & funct3_2 & funct7_1;
112	    wire MULHU  = Rop & funct3_3 & funct7_1;
113	    wire DIV    = Rop & funct3_4 & funct7_1;
114	    wire DIVU   = Rop & funct3_5 & funct7_1;
115	    wire REM    = Rop & funct3_6 & funct7_1;
116	    wire REMU    = Rop & funct3_7 & funct7_1;
117	
118	    wire ADDI  = Iop & funct3_0;	
119	    wire SLTI  = Iop & funct3_2;
120	    wire SLTIU = Iop & funct3_3;
121	    wire XORI  = Iop & funct3_4;
122	    wire ORI   = Iop & funct3_6;
123	    wire ANDI  = Iop & funct3_7;
124	    wire SLLI  = Iop & funct3_1 & funct7_0;
125	    wire SRLI  = Iop & funct3_5 & funct7_0;
126	    wire SRAI  = Iop & funct3_5 & funct7_32;
127	
128	    wire BEQ = Bop & funct3_0;
129	    wire BNE = Bop & funct3_1;
130	    wire BLT = Bop & funct3_4;
131	    wire BGE = Bop & funct3_5;
132	    wire BLTU = Bop & funct3_6;
133	    wire BGEU = Bop & funct3_7;
134	
135	    wire LB =  Lop & funct3_0;
136	    wire LH =  Lop & funct3_1;
137	    wire LW =  Lop & funct3_2;
138	    wire LBU = Lop & funct3_4;
139	    wire LHU = Lop & funct3_5;
140	
141	    wire SB = Sop & funct3_0;
142	    wire SH = Sop & funct3_1;
143	    wire SW = Sop & funct3_2;
144	
145	    wire LUI   = opcode == 7'b0110111;
146	    wire AUIPC = opcode == 7'b0010111;
147	
148	    wire JAL  =  opcode == 7'b1101111;
149	    wire JALR = (opcode == 7'b1100111) && funct3_0;
150	
151	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU 
152	        | MUL | MULH | MULHSU | MULHU | DIV | DIVU | REM | REMU;
153	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
154	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
155	    wire L_valid = LW | LH | LB | LHU | LBU;
156	    wire S_valid = SW | SH | SB;
157	
158	    // function unit specification
159	    wire use_ALU = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU
160	        | I_valid | LUI | AUIPC;
161	    wire use_MEM = L_valid | S_valid;
162	    wire use_MUL = MUL | MULH | MULHSU | MULHU;
163	    wire use_DIV = DIV | DIVU | REM | REMU;
164	    wire use_JUMP = B_valid | JAL | JALR;
165	
166	    wire[2:0] use_FU = {3{use_ALU}}  & `FU_ALU  |
167	                       {3{use_MEM}}  & `FU_MEM  |
168	                       {3{use_MUL}}  & `FU_MUL  |
169	                       {3{use_DIV}}  & `FU_DIV  |
170	                       {3{use_JUMP}} & `FU_JUMP ;
171	
172	    // registers to be used
173	    wire[4:0] dst = {5{R_valid | I_valid | L_valid | LUI | AUIPC | JAL | JALR}} & rd;
174	    wire[4:0] src1 = {5{R_valid | I_valid | S_valid | L_valid | B_valid | JALR}} & rs1;
175	    wire[4:0] src2 = {5{R_valid | S_valid | B_valid}} & rs2;
176	    // initial values of some FUS fields
177	    wire[2:0] fu1 = RRS[src1];
178	    wire[2:0] fu2 = RRS[src2];
179	    wire rdy1 = ~|fu1;
180	    wire rdy2 = ~|fu2;
181	
182	    // normal stall: structural hazard or WAW
183	    assign normal_stall = ...;           //fill sth. here
184	
185	    assign IS_en = IS_flush | ~normal_stall & ~ctrl_stall;
186	    assign RO_en = ~IS_flush & ~normal_stall & ~ctrl_stall;
187	
188	    always @ (posedge clk or posedge rst) begin
189	        if (rst) begin
190	            ctrl_stall <= 0;
191	        end
192	        else begin
193	            // IS
194	            if (RO_en & (use_FU == `FU_JUMP)) begin
195	                ctrl_stall <= 1;
196	            end
197	            else if (JUMP_done) begin
198	                ctrl_stall <= 0;
199	            end
200	        end
201	    end
202	
203	    always @ (posedge clk or posedge rst) begin
204	        if (rst) begin
205	            IS_flush <= 0;
206	        end
207	        else if (JUMP_done & is_jump) begin
208	            IS_flush <= 1;
209	        end
210	        else begin
211	            IS_flush <= 0;
212	        end
213	    end
214	
215	    assign jump_stall = FUS[`FU_JUMP][`BUSY] & (~JUMP_done);
216	
217	    wire[4:0] op = {5{ADD}}          & `ALU_ADD    |
218	                   {5{SUB}}          & `ALU_SUB    |
219	                   {5{AND}}          & `ALU_AND    |
220	                   {5{OR}}           & `ALU_OR     |
221	                   {5{XOR}}          & `ALU_XOR    |
222	                   {5{SLL}}          & `ALU_SLL    |
223	                   {5{SRL}}          & `ALU_SRL    |
224	                   {5{SLT}}          & `ALU_SLT    |
225	                   {5{SLTU}}         & `ALU_SLTU   |
226	                   {5{SRA}}          & `ALU_SRA    |
227	                   {5{LUI}}          & `ALU_LUI    |
228	                   {5{AUIPC}}        & `ALU_AUIPC  |
229	                   {5{ADDI}}         & `ALU_ADDI   |
230	                   {5{ANDI}}         & `ALU_ANDI   |
231	                   {5{ORI}}          & `ALU_ORI    |
232	                   {5{XORI}}         & `ALU_XORI   |
233	                   {5{SLLI}}         & `ALU_SLLI   |
234	                   {5{SRLI}}         & `ALU_SRLI   |
235	                   {5{SLTI}}         & `ALU_SLTI   |
236	                   {5{SLTIU}}        & `ALU_SLTIU  |
237	                   {5{SRAI}}         & `ALU_SRAI   |
238	                   {5{LB}}           & `MEM_LB     |
239	                   {5{LH}}           & `MEM_LH     |
240	                   {5{LW}}           & `MEM_LW     |
241	                   {5{LBU}}          & `MEM_LBU    |
242	                   {5{LHU}}          & `MEM_LHU    |
243	                   {5{SB}}           & `MEM_SB     |
244	                   {5{SH}}           & `MEM_SH     |
245	                   {5{SW}}           & `MEM_SW     |
246	                   {5{MUL}}          & `MUL_MUL    |
247	                   {5{MULH}}         & `MUL_MULH   |
248	                   {5{MULHSU}}       & `MUL_MULHU  |
249	                   {5{MULHU}}        & `MUL_MULHSU |
250	                   {5{DIV}}          & `DIV_DIV    |
251	                   {5{DIVU}}         & `DIV_DIVU   |
252	                   {5{REM}}          & `DIV_REM    |
253	                   {5{REMU}}         & `DIV_REMU   |
254	                   {5{BEQ}}          & `JUMP_BEQ   |
255	                   {5{BNE}}          & `JUMP_BNE   |
256	                   {5{BLT}}          & `JUMP_BLT   |
257	                   {5{BGE}}          & `JUMP_BGE   |
258	                   {5{BLTU}}         & `JUMP_BLTU  |
259	                   {5{BGEU}}         & `JUMP_BGEU  |
260	                   {5{JAL}}          & `JUMP_JAL   |
261	                   {5{JALR}}         & `JUMP_JALR  ;
262	
263	    
264	    assign ImmSel = {3{JALR | L_valid | I_valid}} & `Imm_type_I |
265	                    {3{B_valid}}                  & `Imm_type_B |
266	                    {3{JAL}}                      & `Imm_type_J |
267	                    {3{S_valid}}                  & `Imm_type_S |
268	                    {3{LUI | AUIPC}}              & `Imm_type_U ;
269	
270	    // ensure WAR:
271	    // An FU should not write its results to dst if 
272	    // a previous inst hasn't read that register.
273	    // *_WAR should be driven high when the FU is allowed to write.
274	    // i.e. there is no WAR or when WAR clears
275	    wire ALU_WAR = (
276	        (FUS[`FU_MEM][`SRC1_H:`SRC1_L]  != ... | ...)  &    //fill sth. here
277	        (FUS[`FU_MEM][`SRC2_H:`SRC2_L]  != ... | ...)  &    //fill sth. here
278	        (FUS[`FU_MUL][`SRC1_H:`SRC1_L]  != ... | ...)  &    //fill sth. here
279	        (FUS[`FU_MUL][`SRC2_H:`SRC2_L]  != ... | ...)  &    //fill sth. here
280	        (FUS[`FU_DIV][`SRC1_H:`SRC1_L]  != ... | ...)  &    //fill sth. here
281	        (FUS[`FU_DIV][`SRC2_H:`SRC2_L]  != ... | ...)  &    //fill sth. here
282	        (FUS[`FU_JUMP][`SRC1_H:`SRC1_L] != ... | ...)  &    //fill sth. here
283	        (FUS[`FU_JUMP][`SRC2_H:`SRC2_L] != ... | ...)       //fill sth. here
284	    );
285	
286	    wire MEM_WAR = (
287	        (FUS[`FU_ALU][`SRC1_H:`SRC1_L]  != ... | ...) &    //fill sth. here
288	        (FUS[`FU_ALU][`SRC2_H:`SRC2_L]  != ... | ...) &    //fill sth. here
289	        (FUS[`FU_MUL][`SRC1_H:`SRC1_L]  != ... | ...) &    //fill sth. here
290	        (FUS[`FU_MUL][`SRC2_H:`SRC2_L]  != ... | ...) &    //fill sth. here
291	        (FUS[`FU_DIV][`SRC1_H:`SRC1_L]  != ... | ...) &    //fill sth. here
292	        (FUS[`FU_DIV][`SRC2_H:`SRC2_L]  != ... | ...) &    //fill sth. here
293	        (FUS[`FU_JUMP][`SRC1_H:`SRC1_L] != ... | ...) &    //fill sth. here
294	        (FUS[`FU_JUMP][`SRC2_H:`SRC2_L] != ... | ...)      //fill sth. here
295	    );
296	
297	    wire MUL_WAR = (
298	        (FUS[`FU_ALU][`SRC1_H:`SRC1_L] != ... | ...) &     //fill sth. here
299	        (FUS[`FU_ALU][`SRC2_H:`SRC2_L] != ... | ...) &     //fill sth. here
300	        (FUS[`FU_MEM][`SRC1_H:`SRC1_L] != ... | ...) &     //fill sth. here
301	        (FUS[`FU_MEM][`SRC2_H:`SRC2_L] != ... | ...) &     //fill sth. here
302	        (FUS[`FU_DIV][`SRC1_H:`SRC1_L] != ... | ...) &     //fill sth. here
303	        (FUS[`FU_DIV][`SRC2_H:`SRC2_L] != ... | ...) &     //fill sth. here
304	        (FUS[`FU_JUMP][`SRC1_H:`SRC1_L]!= ... | ...) &     //fill sth. here
305	        (FUS[`FU_JUMP][`SRC2_H:`SRC2_L]!= ... | ...)       //fill sth. here
306	    );
307	
308	    wire DIV_WAR = (
309	        (FUS[`FU_ALU][`SRC1_H:`SRC1_L] != ... | ...) &      //fill sth. here
310	        (FUS[`FU_ALU][`SRC2_H:`SRC2_L] != ... | ...) &      //fill sth. here
311	        (FUS[`FU_MEM][`SRC1_H:`SRC1_L] != ... | ...) &      //fill sth. here
312	        (FUS[`FU_MEM][`SRC2_H:`SRC2_L] != ... | ...) &      //fill sth. here
313	        (FUS[`FU_MUL][`SRC1_H:`SRC1_L] != ... | ...) &      //fill sth. here
314	        (FUS[`FU_MUL][`SRC2_H:`SRC2_L] != ... | ...) &      //fill sth. here
315	        (FUS[`FU_JUMP][`SRC1_H:`SRC1_L]!= ... | ...) &      //fill sth. here
316	        (FUS[`FU_JUMP][`SRC2_H:`SRC2_L]!= ... | ...)        //fill sth. here
317	    );
318	
319	    wire JUMP_WAR = (
320	        (FUS[`FU_ALU][`SRC1_H:`SRC1_L] != ... | ...) &      //fill sth. here
321	        (FUS[`FU_ALU][`SRC2_H:`SRC2_L] != ... | ...) &      //fill sth. here
322	        (FUS[`FU_MEM][`SRC1_H:`SRC1_L] != ... | ...) &      //fill sth. here
323	        (FUS[`FU_MEM][`SRC2_H:`SRC2_L] != ... | ...) &      //fill sth. here
324	        (FUS[`FU_MUL][`SRC1_H:`SRC1_L] != ... | ...) &      //fill sth. here
325	        (FUS[`FU_MUL][`SRC2_H:`SRC2_L] != ... | ...) &      //fill sth. here
326	        (FUS[`FU_DIV][`SRC1_H:`SRC1_L] != ... | ...) &      //fill sth. here
327	        (FUS[`FU_DIV][`SRC2_H:`SRC2_L] != ... | ...)        //fill sth. here
328	    );
329	
330	    // maintain the table
331	    always @ (posedge clk or posedge rst) begin
332	        if (rst) begin
333	            // reset the scoreboard
334	            for (i = 0; i < 32; i = i + 1) begin
335	                RRS[i] <= 3'b0;
336	            end
337	
338	            for (i = 1; i <= 5; i = i + 1) begin
339	                FUS[i] <= 32'b0;
340	                IMM[i] <= 32'b0;
341	            end
342	        end
343	
344	        else begin
345	            // IS
346	            if (RO_en) begin
347	                // not busy, no WAW, write info to FUS and RRS
348	                if (|dst) RRS[dst] <= use_FU;
349	                FUS[use_FU][`BUSY] <= 1'b1;
350	                ...                             //fill sth. here.
351	                
352	                IMM[use_FU] <= imm;
353	                PCR[use_FU] <= PC;
354	            end
355	
356	            // RO
357	            if (FUS[`FU_JUMP][`RDY1] & FUS[`FU_JUMP][`RDY2]) begin
358	                // JUMP
359	                FUS[`FU_JUMP][`RDY1] <= 1'b0;
360	                FUS[`FU_JUMP][`RDY2] <= 1'b0;
361	                FUS[`FU_JUMP][`FU1_H:`FU1_L] <= 3'b0;
362	                FUS[`FU_JUMP][`FU2_H:`FU2_L] <= 3'b0;
363	            end
364	            else if (...) begin             //fill sth. here.
365	                // ALU
366	                ...                         //fill sth. here.
367	            end
368	            else if (..) begin             //fill sth. here.
369	                // MEM
370	                ...                         //fill sth. here.
371	            end
372	            else if (...) begin             //fill sth. here.
373	                // MUL
374	                ...                         //fill sth. here.
375	            end
376	            else if (..) begin             //fill sth. here.
377	                // DIV
378	                ...                         //fill sth. here.
379	            end
380	
381	            // EX
382	            FUS[`FU_ALU][`FU_DONE] <= ...   //fill sth. here
383	            ...                             //fill sth. here
384	
385	            // WB
386	            if (FUS[`FU_JUMP][`FU_DONE] & JUMP_WAR) begin
387	                FUS[`FU_JUMP] <= 32'b0;
388	                RRS[FUS[`FU_JUMP][`DST_H:`DST_L]] <= 3'b0;
389	
390	                // ensure RAW
391	                if (FUS[`FU_ALU][`FU1_H:`FU1_L] == `FU_JUMP) ...;           //fill sth. here
392	                if (FUS[`FU_MEM][`FU1_H:`FU1_L] == `FU_JUMP) ...;           //fill sth. here
393	                if (FUS[`FU_MUL][`FU1_H:`FU1_L] == `FU_JUMP) ...;           //fill sth. here
394	                if (FUS[`FU_DIV][`FU1_H:`FU1_L] == `FU_JUMP) ...;           //fill sth. here
395	
396	                if (FUS[`FU_ALU][`FU2_H:`FU2_L] == `FU_JUMP) ...;           //fill sth. here
397	                if (FUS[`FU_MEM][`FU2_H:`FU2_L] == `FU_JUMP) ...;           //fill sth. here
398	                if (FUS[`FU_MUL][`FU2_H:`FU2_L] == `FU_JUMP) ...;           //fill sth. here
399	                if (FUS[`FU_DIV][`FU2_H:`FU2_L] == `FU_JUMP)...;           //fill sth. here
400	            end
401	            // ALU
402	                ...;           //fill sth. here
403	            // MEM
404	                ...;           //fill sth. here
405	            // MUL
406	                ...;           //fill sth. here
407	            // DIV
408	                ...;           //fill sth. here
409	        end
410	    end
411	
412	    // ctrl signals should be combinational logic
413	    // RO
414	    always @ (*) begin
415	        ALU_en = 0;
416	        MEM_en = 0;
417	        MUL_en = 0;
418	        DIV_en = 0;
419	        JUMP_en = 0;
420	
421	        rs1_ctrl = 0;
422	        rs2_ctrl = 0;
423	        PC_ctrl = 0;
424	        imm_ctrl = 0;
425	        JUMP_op = 0;
426	        ALU_op = 0;
427	        ALU_use_PC = 0;
428	        ALU_use_imm = 0;
429	        MEM_we = 0;
430	        MEM_bhw = 0;
431	        MUL_op = 0;
432	        DIV_op = 0;
433	
434	        // JUMP
435	        if (FUS[`FU_JUMP][`RDY1] & FUS[`FU_JUMP][`RDY2]) begin
436	            ALU_en = 1'b0;
437	            MEM_en = 1'b0;
438	            MUL_en = 1'b0;
439	            DIV_en = 1'b0;
440	            JUMP_en = 1'b1;
441	
442	            JUMP_op = FUS[`FU_JUMP][`OP_H:`OP_L];
443	            rs1_ctrl = FUS[`FU_JUMP][`SRC1_H:`SRC1_L];
444	            rs2_ctrl = FUS[`FU_JUMP][`SRC2_H:`SRC2_L];
445	            PC_ctrl = PCR[`FU_JUMP];
446	            imm_ctrl = IMM[`FU_JUMP];
447	        end
448	        // ALU
449	        else if (FUS[`FU_ALU][`RDY1] & FUS[`FU_ALU][`RDY2]) begin
450	            ALU_en = 1'b1;
451	            MEM_en = 1'b0;
452	            MUL_en = 1'b0;
453	            DIV_en = 1'b0;
454	            JUMP_en = 1'b0;
455	
456	            ALU_op = FUS[`FU_ALU][`OP_H:`OP_L] == `ALU_AUIPC ? 
457	                      4'b0001 : FUS[`FU_ALU][`OP_L+3:`OP_L];
458	            rs1_ctrl = FUS[`FU_ALU][`SRC1_H:`SRC1_L];
459	            rs2_ctrl = FUS[`FU_ALU][`SRC2_H:`SRC2_L];
460	            ALU_use_PC = FUS[`FU_ALU][`OP_H:`OP_L] == `ALU_AUIPC;
