464	        end
465	        // MEM
466	        else if (FUS[`FU_MEM][`RDY1] & FUS[`FU_MEM][`RDY2]) begin
467	            ALU_en = 1'b0;
468	            MEM_en = 1'b1;
469	            MUL_en = 1'b0;
470	            DIV_en = 1'b0;
471	            JUMP_en = 1'b0;
472	
473	            MEM_we = FUS[`FU_MEM][`OP_L];
474	            MEM_bhw = FUS[`FU_MEM][`OP_L+3:`OP_L+1];
475	            rs1_ctrl = FUS[`FU_MEM][`SRC1_H:`SRC1_L];
476	            rs2_ctrl = FUS[`FU_MEM][`SRC2_H:`SRC2_L];   // if store
477	            imm_ctrl = IMM[`FU_MEM];
478	        end
479	        // MUL
480	        else if (FUS[`FU_MUL][`RDY1] & FUS[`FU_MUL][`RDY2]) begin
481	            ALU_en = 1'b0;
482	            MEM_en = 1'b0;
483	            MUL_en = 1'b1;
484	            DIV_en = 1'b0;
485	            JUMP_en = 1'b0;
486	
487	            MUL_op = FUS[`FU_MUL][`OP_L+2:`OP_L];
488	            rs1_ctrl = FUS[`FU_MUL][`SRC1_H:`SRC1_L];
489	            rs2_ctrl = FUS[`FU_MUL][`SRC2_H:`SRC2_L];
490	        end
491	        else if (FUS[`FU_DIV][`RDY1] & FUS[`FU_DIV][`RDY2]) begin
492	            ALU_en = 1'b0;
493	            MEM_en = 1'b0;
494	            MUL_en = 1'b0;
