500	            rs2_ctrl = FUS[`FU_DIV][`SRC2_H:`SRC2_L];
501	        end
502	    end
503	
504	    // WB
505	    always @ (*) begin
506	        write_sel = 0;
507	        reg_write = 0;
508	        rd_ctrl = 0;
509	
510	        if (FUS[`FU_JUMP][`FU_DONE] & JUMP_WAR) begin
511	            write_sel = 3'd4;
512	            reg_write = 1'b1;
513	            rd_ctrl = FUS[`FU_JUMP][`DST_H:`DST_L];
514	        end
515	        else if (FUS[`FU_ALU][`FU_DONE] & ALU_WAR) begin
516	            write_sel = 3'd0;
517	            reg_write = 1'b1;
518	            rd_ctrl = FUS[`FU_ALU][`DST_H:`DST_L];
519	        end
520	        else if (FUS[`FU_MEM][`FU_DONE] & MEM_WAR) begin
521	            write_sel = 3'd1;
522	            reg_write = 1'b1;
523	            rd_ctrl = FUS[`FU_MEM][`DST_H:`DST_L];
524	        end
